import{_ as a,o as r,c as e,ag as o}from"./chunks/framework.CPvOxTBX.js";const g=JSON.parse('{"title":"搜索模式","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/search-modes.md","filePath":"zh/guide/search-modes.md","lastUpdated":1794494042000}'),d={name:"zh/guide/search-modes.md"};function s(n,t,l,h,i,c){return r(),e("div",null,t[0]||(t[0]=[o('<h1 id="搜索模式" tabindex="-1">搜索模式 <a class="header-anchor" href="#搜索模式" aria-label="Permalink to &quot;搜索模式&quot;">​</a></h1><p>搜索栏提供四种不同的查词方式。点击搜索栏右侧的<strong>模式按钮</strong>（展开搜索视图后，它也在清空键 ✕ 旁边），即可在四种模式间循环切换。当前模式由图标表示，长按还会显示「搜索模式：正序」之类的提示。你的选择会被保存，下次打开词悦时自动恢复。</p><p>四种模式（按循环顺序）：</p><table tabindex="0"><thead><tr><th>模式</th><th>图标</th><th>匹配规则</th><th>是否需要全文索引</th></tr></thead><tbody><tr><td>正序（默认）</td><td>⏮</td><td>词头<strong>以</strong>输入内容开头。</td><td>否</td></tr><tr><td>倒序</td><td>⏭</td><td>词头<strong>以</strong>输入内容结尾。</td><td>是</td></tr><tr><td>多词</td><td>🔗</td><td>词头<strong>同时包含</strong>输入的每个词，不要求相邻。</td><td>是</td></tr><tr><td>全文</td><td>🔍</td><td>在<strong>释义</strong>中匹配，而非仅词头。</td><td>是</td></tr></tbody></table><h2 id="正序-——-默认模式" tabindex="-1">正序 —— 默认模式 <a class="header-anchor" href="#正序-——-默认模式" aria-label="Permalink to &quot;正序 —— 默认模式&quot;">​</a></h2><p>词头以你输入内容开头的词条，例如输入 <code>app</code> 会得到 <code>apple</code>、<code>application</code>。这是词悦原本的查词行为，无需任何设置——词典载入后即可使用。</p><h2 id="倒序-——-逆引词典" tabindex="-1">倒序 —— 逆引词典 <a class="header-anchor" href="#倒序-——-逆引词典" aria-label="Permalink to &quot;倒序 —— 逆引词典&quot;">​</a></h2><p>词头<strong>以</strong>输入内容<strong>结尾</strong>的词条，可以「揪着尾巴查词」。这正是倒序词典（逆引词典）的思路：当你只记得结尾、想不起完整词条时，输入结尾字即可列出所有以它收尾的词。例如只记得「×动」、想不起「翕动」，输入「动」会列出按兵不动、摆动、半自动、暴动、被动……再从中挑出想找的那个。</p><p>倒序匹配由全文索引中新增的「反转词头」列提供，因此依赖该索引（见下文）。</p><h2 id="多词-——-多词组合" tabindex="-1">多词 —— 多词组合 <a class="header-anchor" href="#多词-——-多词组合" aria-label="Permalink to &quot;多词 —— 多词组合&quot;">​</a></h2><p>词头<strong>同时包含</strong>你输入的每一个字，顺序不限、不要求相邻。例如输入「中国」或「中 国」，结果里既有二字相邻、正序的「中国」，也有相邻但倒序的「国中」，以及包含相邻「中国」二字的「中国通」「大秦景教流行中国碑」、被其他字隔开的「中立国」「中华民国鄂州约法」「中华民国北伐铁血团」……每个词头都同时含有「中」和「国」，但二者不必相邻、也不必按序，是「正序」「倒序」都表达不了的意图。</p><h2 id="全文-——-检索释义" tabindex="-1">全文 —— 检索释义 <a class="header-anchor" href="#全文-——-检索释义" aria-label="Permalink to &quot;全文 —— 检索释义&quot;">​</a></h2><p>在<strong>释义内容</strong>中匹配你的输入，而不只是词头。输入一个概念或短语，词悦会列出所有正文提及它的词条，并附上上下文片段。其引擎与独立的「在释义中搜索」一致，现在直接集成到了搜索栏中。</p><h2 id="全文索引" tabindex="-1">全文索引 <a class="header-anchor" href="#全文索引" aria-label="Permalink to &quot;全文索引&quot;">​</a></h2><p>倒序、多词、全文三种模式都读取<strong>全文索引</strong>（词悦按词典逐个构建），正序不使用它。</p><p>首次使用这三种模式之一时，词悦会在后台开始构建索引——与全文页进行的构建相同。在索引就绪之前，搜索栏会以状态行代替结果：</p><ul><li><strong>正在构建……</strong> —— 索引正在生成，完成后结果自动出现。</li><li><strong>索引未构建</strong> —— 点击它打开全文页，在那里构建并显示进度。</li><li><strong>索引构建失败</strong> —— 点击它到全文页重试。</li></ul><p>你也可以一次性构建和管理所有词典的索引：<strong>设置 → 管理词典 → 索引总览图标</strong>，那里列出每本词典的索引状态、磁盘占用，以及构建 / 取消 / 重建等操作。</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="./word-forms.html">词形还原</a> —— 把变形词还原到词根。</li><li><a href="./getting-started.html">快速上手</a> —— 添加词典。</li><li><a href="https://github.com/mumu-lhl/Ciyue/issues/824" target="_blank" rel="noreferrer">Issue #824</a> —— 引入搜索模式的提案。</li></ul>',20)]))}const u=a(d,[["render",s]]);export{g as __pageData,u as default};
